// CatalogDefect is a deliberately broken implementation, used as
// evidence that a check can fail. In practice you build one with
// BrokenCatalog over the generated test double.
type CatalogDefect interface {
	Subject(docs CatalogCorpus) (CatalogSubject, error)
}

// BrokenCatalog describes an implementation built to break one
// specific claim, so that a check can be shown to catch it.
//
// Give it a name saying what is wrong, and a constructor. The best
// broken implementation is the generated double wrapping a correct one,
// with a single method overridden — correct everywhere except the one
// place the check is about.
//
// It receives the same starting data a real implementation would, since
// what you are breaking here is what it does with what it was given.
func BrokenCatalog[T Catalog](
	name string, build func(docs CatalogCorpus) T,
) CatalogHarness[T] {
	return CatalogHarness[T]{
		Name: name, Seed: build,
	}
}

// CatalogChecks is a table of checks you write yourself, for the
// claims that cannot be worked out from the declaration — the ones that
// carry your domain.
//
// They are the same kind of value as the generated checks: they appear
// in the report, they can be dropped by name, and they can say what they
// need from an implementation. There is no second mechanism for them.
//
//	var myChecks = CatalogChecks{
//		{Method: "Lookup", Name: "my-claim",
//			Claim:    "a sentence stating exactly what this check proves",
//			Run:      myClaimBody,
//			ProvenBy: BrokenCatalog("an implementation that breaks it", newBroken)},
//	}
type CatalogChecks []CatalogCheck

func (c CatalogChecks) applyTo(rc *catalogRunConfig) {
	rc.rows = append(rc.rows, c...)
}

// CatalogCheck is one check you wrote. The body is a plain named
// function; which field you put it in decides what it is handed.
type CatalogCheck struct {
	// Method groups this check under one of your methods, so it is named
	// Lookup/<Name> in output and reruns with the rest of that
	// method's checks. Leave it empty for a check that is not about one
	// method in particular.
	Method string

	// Name identifies this check, in output and when dropping it. Keep it
	// stable: it is what a colleague's Without call refers to.
	Name string

	// Claim is one sentence saying exactly what this check proves. It is
	// recorded in the manifest and read out in the report.
	//
	// Write only what the body actually establishes. "a second write
	// leaves the value unchanged" is a promise that something reads the
	// value back; if the body only checks the write returned no error,
	// say that instead. Nothing here can catch a claim that is wider
	// than its check, and a claim nobody verifies is worse than none.
	Claim string

	// Set exactly one.
	//
	// Run is handed one fresh instance, which suits nearly every check.
	// RunWith is handed something that can build instances, for a claim
	// one instance cannot state on its own: build two and compare them,
	// move the clock forward, put one into a failure state.
	//
	// Both are also handed the sample inputs, so a check you write draws
	// from the same values the generated ones do — override an input and
	// your check sees the override too.
	Run     func(tb testing.TB, s Catalog, fx CatalogFixture)
	RunWith func(tb testing.TB, sub CatalogSubject, fx CatalogFixture)

	// Class groups this check in the report's summary. Optional; checks
	// you write are grouped as hand-written by default.
	Class suite.Class

	// Needs says what this check requires from an implementation beyond
	// being constructed — a clock it can move, a failure it can induce.
	//
	// An implementation that cannot supply it fails this check by name,
	// with the field to fill in named in the message. It never skips: a
	// check that quietly skipped for want of wiring would look exactly
	// like one that passed.
	Needs suite.Caps

	// ProvenBy is an implementation built to break this check and nothing
	// else. Setting it makes two statements at once — that the check can
	// fail, and here is the proof — and ProveCatalog fails unless the
	// broken implementation really does turn this check red.
	//
	// ProvenReason, if set, is text the failure must contain. Use it so
	// that a broken implementation which fails for some unrelated reason
	// stops counting as evidence.
	//
	// Argued is for when no such implementation can be built: record why,
	// in a sentence. Set at most one of the two. Setting neither is
	// allowed and the report says so — the check is unproven, which is
	// honest, and different from proven.
	ProvenBy     CatalogDefect
	ProvenReason string
	Argued       string
}

// catalogMethods is the interface's method names, used to catch a typo in
// a check's Method field before the run starts.
//
// Without it a misspelled name would be accepted — it looks like any
// other method name — and the check would be filed under a method that
// does not exist, where nobody could find or drop it.
var catalogMethods = suite.NewNameSet("Catalog", catalogLookup, catalogLen)

// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c CatalogCheck) bind(
	fx CatalogFixture,
) (suite.Check[Catalog], error) {
	out := suite.Check[Catalog]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error
	bodies := 0
	if c.Run != nil {
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, catalogMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s Catalog) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub CatalogSubject) {
			rw(tb, sub, fx)
		}
	}
	if err := suite.OneBody(c.Name, bodies, "Run, RunWith"); err != nil {
		return out, err
	}
	if c.Method != "" && c.Run == nil {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunCatalog runs every check — the generated ones and any you
// wrote — against every implementation you pass it.
//
// Each argument describes one thing to do, in any order: an
// implementation to test, a table of your own checks, sample inputs to
// use, or checks to leave out.
//
//	RunCatalog(t,
//		CatalogHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		CatalogSuite.Without(CatalogSuite.Checks.Lookup.Smoke()),
//	)
//
// Pass two implementations to compare them against each other, and mark
// the one you trust as the Oracle. Every check runs as its own subtest
// named after the implementation and the check, so `go test -run` can
// select one.
//
// A check that needs something your implementation has not supplied
// fails rather than skipping, and says which field to fill in. That is
// deliberate: a skipped check is how a claim goes unchecked while the
// run stays green.
func RunCatalog(
	t *testing.T, opts ...CatalogRunOpt,
) {
	t.Helper()
	var rc catalogRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := catalogNewFixture(rc.cfg)
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Checked here, after reading every argument and before running
	// anything: a misconfigured run reports all of its problems at once
	// rather than one per attempt.
	rc.Fail(t, "RunCatalog")
	suite.Run(t,
		catalogSuite(fx, catalogCorpus(rc.cfg)).With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveCatalog runs each of your checks against the deliberately
// broken implementation it names, and fails if the check does not catch
// it.
//
//	func TestMyChecksCanFail(t *testing.T) { ProveCatalog(t, myChecks) }
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
func ProveCatalog(
	t *testing.T, checks CatalogChecks, cfg ...CatalogConfig,
) {
	t.Helper()
	if len(cfg) > 1 {
		t.Fatalf("ProveCatalog: %d configs passed; pass at most one", len(cfg))
	}
	var c CatalogConfig
	if len(cfg) == 1 {
		c = cfg[0]
	}
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := catalogNewFixture(c)
	bound := make([]suite.Check[Catalog], 0, len(checks))
	defects := prove.Defects[Catalog]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveCatalog: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject(catalogCorpus(c))
		if err != nil {
			t.Fatalf("ProveCatalog: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Catalog]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

